head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil17300";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil17300.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_searchWord", fn: function () { return String((dma_pageContext.get("searchWord") ?? "")); } },
        { childId: "cal_startDate", fn: function () { return String((dma_pageContext.get("startDate") ?? "")); } },
        { childId: "cal_endDate", fn: function () { return String((dma_pageContext.get("endDate") ?? "")); } },
        { childId: "__rb0", fn: function () { return " 전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        // showMessage();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil17300.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_search();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cal_startDate_onblur
 * @description cal_startDate 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_startDate_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_startDate"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17300.cal_startDate_onblur' }); }
};

/**
 * @method
 * @name cal_endDate_onblur
 * @description cal_endDate 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_endDate_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_endDate"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17300.cal_endDate_onblur' }); }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17300.btn_search_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17300.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_qnaList_oncellclick
 * @description grd_qnaList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_qnaList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_qnaList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_qnaList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.searchQnaView(r["quesReadYn"], r["contnId"], r["contnGrpId"], r["ansObjContnId"], r["notiObjSysTpCd"], r["contnAttachSeq"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_qnaList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_goWriteQna_onclick
 * @description 「질문작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goWriteQna_onclick = async function(e){
    try {
        await scwin.goWriteQna()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil17300.btn_goWriteQna_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_142_onclick
 * @description krxpage_pagenavigator_142 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_142_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_142.page' }); } await scwin.tx_fn_search(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_goWriteQna
 * @description go Write Qna 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWriteQna = async function () {
    const sbmOptions = {
        id: "tx_fn_goWriteQna",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_goWriteQnaReq",
        target: "dlt_qnaList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_searchReq",
        target: "dlt_qnaList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_142").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

/**
 * @method
 * @name tx_fn_SearchQnaView
 * @description Search Qna View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchQnaView = async function () {
    const sbmOptions = {
        id: "tx_fn_SearchQnaView",
        method: "post",
        action: "/support/qna.do",
        ref: "dma_SearchQnaViewReq",
        target: "dlt_qnaList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_qnaList_fmt_column2
 * @description grd qna List fmt column2 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_qnaList_fmt_column2 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_qnaList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "quesBzTpCd") ?? '') : '');
        if (v === '1') { return "상장"; }
        if (v === '2') { return "공시"; }
        if (v === '3') { return "지분"; }
        if (v === '9') { return "기타"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_qnaList.column2" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_qnaList_fmt_quesTitle
 * @description grd qna List fmt ques Title 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_qnaList_fmt_quesTitle = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_qnaList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "contnDepth") ?? '') : '');
        if (v !== '1') { return (console.error('[sdd] 미실현 라벨 갈래: quesTitle (image)'), String(data ?? '')); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_qnaList.quesTitle" }); return String(data ?? ''); }
};

/**
 * @method
 * @name goWriteQna
 * @description go Write Qna 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWriteQna = async function () {
    const frm = (document.QnaInfoForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goWriteQnaReq').set('method', 'writeQna');
    const nr = await scwin.tx_fn_goWriteQna();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil17301/jldfil17301.xml", { "method": 'writeQna' });
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.QnaListForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goWriteQnaReq').set('method', 'searchQnaList');
    await scwin.tx_fn_search();
};

/**
 * @method
 * @name searchQnaView
 * @description search Qna View 처리
 * @param {String} quesReadYn quesReadYn
 * @param {String} contnId contnId
 * @param {String} contnGrpId contnGrpId
 * @param {String} ansObjContnId ansObjContnId
 * @param {String} notiObjSysTpCd notiObjSysTpCd
 * @param {*} contnAttachSeq contnAttachSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchQnaView = async function (quesReadYn, contnId, contnGrpId, ansObjContnId, notiObjSysTpCd, contnAttachSeq) {
    if (quesReadYn === 'Y') {
        const frm = (document.QnaListForm || { elements: [] });
        frm.action = 'qna.do';
        $c.util.getComponent('dma_goWriteQnaReq').set('method', 'searchQnaView');
        $c.util.getComponent('dma_goWriteQnaReq').set('contnId', contnId);
        $c.util.getComponent('dma_goWriteQnaReq').set('contnGrpId', contnGrpId);
        $c.util.getComponent('dma_goWriteQnaReq').set('ansObjContnId', ansObjContnId);
        $c.util.getComponent('dma_goWriteQnaReq').set('notiObjSysTpCd', notiObjSysTpCd);
        $c.util.getComponent('dma_goWriteQnaReq').set('contnAttachSeq', contnAttachSeq);
        const nr = await scwin.tx_fn_SearchQnaView();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/jldfil17302/jldfil17302.xml", { "method": 'searchQnaView', "contnId": contnId, "contnGrpId": contnGrpId, "ansObjContnId": ansObjContnId, "notiObjSysTpCd": notiObjSysTpCd, "contnAttachSeq": contnAttachSeq });
        }
    } else {
        await $c.win.alert('비공개로 작성된 글은 작성자만 볼 수 있습니다.');
        return;
    }
};
